args.sql:
SELECT 
    ROUND(CAST(p.cloud_metrics->>'Total_Pts' AS numeric) / CAST(p.cloud_metrics->>'Cloud_Dense' AS numeric), 6) as pcdr_with_cloud_dense
FROM pointcloud p LIMIT 5;
